<?php
use Moves\Services\{CostCenters,Finance,FinanceContext,OrganizationContext};$e=static fn($v):string=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$rows=[];$error=null;try{if(OrganizationContext::current()===null)throw new InvalidArgumentException('Centros de custo estão disponíveis apenas para empresas.');$rows=(new CostCenters((int)FinanceContext::currentId()))->all(true);}catch(Throwable $x){$error=$x->getMessage();}$flash=$_SESSION['finance_flash']??null;unset($_SESSION['finance_flash']); ?>
<?php if(is_array($flash)): ?><p class="finance-flash finance-flash-<?= $e($flash[0]) ?>" role="status"><?= $e($flash[1]) ?></p><?php endif; ?><section class="card finance-workspace"><div class="finance-toolbar"><div><h2>Centros de custo</h2><p class="muted">Classifique áreas, projetos ou unidades sem alterar os lançamentos já existentes.</p></div><button type="button" class="primary" data-finance-open="cost-center">+ Novo centro</button></div><?php if($error): ?><div class="finance-empty"><h3>Indisponível</h3><p><?= $e($error) ?></p></div><?php elseif($rows===[]): ?><div class="finance-empty"><h3>Nenhum centro cadastrado</h3><p>Crie o primeiro centro de custo para a empresa.</p></div><?php else: ?><div class="finance-table-wrap"><table class="finance-table"><thead><tr><th>Centro</th><th>Código</th><th>Situação</th><th class="num">Receitas</th><th class="num">Despesas</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= $e($r['name']) ?></td><td><?= $e($r['code']??'—') ?></td><td><?= $e($r['status']==='active'?'Ativo':'Inativo') ?></td><td class="num green"><?= $e(Finance::money((int)$r['income_cents'])) ?></td><td class="num red"><?= $e(Finance::money((int)$r['expense_cents'])) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section><dialog class="finance-dialog" id="cost-center"><form method="post" action="/minha-conta/financeiro/centro-de-custo"><header><h2>Novo centro de custo</h2><button type="button" data-finance-close>×</button></header><input type="hidden" name="csrf_token" value="<?= $e($csrf) ?>"><input type="hidden" name="back" value="centros-de-custo"><label>Nome<input name="name" maxlength="100" required></label><label>Código (opcional)<input name="code" maxlength="40"></label><footer><button type="button" data-finance-close>Cancelar</button><button class="primary">Salvar</button></footer></form></dialog>
